cd /Users/sinchunyeung/github/simplification-of-trajectory-streams && \
python3 -m http.server 8765 --directory web >/tmp/usability-http.log 2>&1 &
HTTP_PID=$!
sleep 0.5
export PLAYWRIGHT_BROWSERS_PATH="$HOME/Library/Caches/ms-playwright"
node <<'NODE'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.goto('http://127.0.0.1:8765/', { waitUntil: 'domcontentloaded', timeout: 15000 });
  const skip = page.locator('#uiTourSkip');
  if (await skip.isVisible().catch(() => false)) await skip.click();
  const instr = await page.locator('#dropHint .desktop-instructions').innerText();
  const picker = await page.locator('#preloadedLabel').innerText();
  const pickerH2 = await page.locator('#tracePicker h2').innerText();
  const scrollW = await page.evaluate(() => document.documentElement.scrollWidth);
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await mobile.goto('http://127.0.0.1:8765/', { waitUntil: 'domcontentloaded', timeout: 15000 });
  const mSkip = mobile.locator('#uiTourSkip');
  if (await mSkip.isVisible().catch(() => false)) await mSkip.click();
  const mPicker = await mobile.locator('#preloadedLabel').innerText();
  const mScroll = await mobile.evaluate(() => document.documentElement.scrollWidth);
  const mHelp = await mobile.locator('.mobile-start-help').innerText();
  console.log(JSON.stringify({
    desktop: {
      picker, pickerH2, scrollW,
      hasKbdStep: instr.includes('Previous / next step'),
      hasStartPath: instr.includes('preloaded trajectory') && instr.includes('Load Trace'),
      instrPreview: instr.slice(0, 280),
    },
    mobile: {
      picker: mPicker, scrollW: mScroll,
      hasTrajectory: mHelp.includes('preloaded trajectory'),
    }
  }, null, 2));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
NODE
NODE_STATUS=$?
kill $HTTP_PID 2>/dev/null
wait $HTTP_PID 2>/dev/null
# Also check server tests if any quick ones
python3 -m py_compile web/server.py 2>&1 | head -5
exit $NODE_STATUS
